import{_ as t,o,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Thiết kế DA-570: Tiền xử lý văn bản, Lọc Bot/Spam & Chuẩn hóa NLP (T0–T2.5)","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/text-normalization-pipeline-design.md","filePath":"ai-models/text-normalization-pipeline-design.md"}'),d={name:"ai-models/text-normalization-pipeline-design.md"};function i(a,e,r,h,l,s){return o(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="thiet-ke-da-570-tien-xu-ly-van-ban-loc-bot-spam-chuan-hoa-nlp-t0–t2-5" tabindex="-1">Thiết kế DA-570: Tiền xử lý văn bản, Lọc Bot/Spam &amp; Chuẩn hóa NLP (T0–T2.5) <a class="header-anchor" href="#thiet-ke-da-570-tien-xu-ly-van-ban-loc-bot-spam-chuan-hoa-nlp-t0–t2-5" aria-label="Permalink to &quot;Thiết kế DA-570: Tiền xử lý văn bản, Lọc Bot/Spam &amp; Chuẩn hóa NLP (T0–T2.5)&quot;">​</a></h1><p>&gt; <a href="./../">&lt;&lt; Knowledge Base Home</a> · <a href="./README.html">AI Models &amp; Research</a> · <a href="./../architecture/ai-service-architecture.html">AI Service Architecture</a></p><h2 id="_1-muc-tieu-objective" tabindex="-1">1. Mục tiêu (Objective) <a class="header-anchor" href="#_1-muc-tieu-objective" aria-label="Permalink to &quot;1. Mục tiêu (Objective)&quot;">​</a></h2><p>Xây dựng chuỗi tầng tiền xử lý đầu vào (<code>T0</code> → <code>T1</code> → <code>T2</code> → <code>T2.5</code>) trong <code>brandhub-ai-service/app/services/pipeline/</code> cho hệ thống <strong>Trend Detection &amp; Social Listening (<code>FR 3.7.15</code>–<code>3.7.19</code>)</strong>:</p><ul><li><strong><code>T0</code> — Ingestion (<code>t0_ingest_step.py</code>)</strong>: Nạp, chuẩn hóa schema đa nguồn (TikTok, Facebook, Google Trends, News) và khử trùng lặp 2 lớp.</li><li><strong><code>T1</code> — Bot/Clone/Spam Filter (<code>t1_spam_filter_step.py</code>)</strong>: Loại bỏ seeding/bot tự động và gắn cờ tương tác ảo trước khi tính toán thống kê.</li><li><strong><code>T2</code> — NLP &amp; PhoBERT Labeling (<code>t2_nlp_step.py</code> — <code>NLPStep</code>)</strong>: Làm sạch văn bản tiếng Việt, gán nhãn chủ đề + 7 cảm xúc + thực thể tên riêng (NER) bằng <strong>PhoBERT</strong>, kết hợp khôi phục cụm danh từ riêng (<code>Np</code>) qua <code>underthesea.pos_tag</code>.</li><li><strong><code>T2.5</code> — Low-Confidence LLM Disambiguation (<code>t2_5_label_check_step.py</code>)</strong>: Kiểm định lại bằng Claude đối với các bài đăng có độ tự tin phân loại chủ đề (<code>topic_confidence</code>) thấp từ PhoBERT.</li></ul><hr><h2 id="_2-kien-truc-t0-—-ingestion-parse-2-layer-deduplication" tabindex="-1">2. Kiến trúc <code>T0</code> — Ingestion (Parse + 2-Layer Deduplication) <a class="header-anchor" href="#_2-kien-truc-t0-—-ingestion-parse-2-layer-deduplication" aria-label="Permalink to &quot;2. Kiến trúc `T0` — Ingestion (Parse + 2-Layer Deduplication)&quot;">​</a></h2><p><strong>Đầu vào:</strong> Luồng dữ liệu JSON/NDJSON thô từ các adapter cào mạng xã hội (<code>TikTok</code>, <code>Facebook</code>, <code>Google Trends</code>).</p><p><strong>Quy trình xử lý:</strong></p><ol><li><strong>Chuẩn hóa cấu trúc (<code>RawTrendItem</code>):</strong><ul><li>Nội dung gốc (<code>raw_text</code> hợp nhất từ <code>text</code>, <code>raw</code>, <code>message</code>, <code>content</code>).</li><li>Định danh tác giả (<code>author</code>, <code>external_id</code>) và thời điểm thu thập (<code>crawled_at</code>).</li><li>Tương tác chi tiết: Đọc đủ <strong>7 loại Reaction</strong> (<code>like</code>, <code>love</code>, <code>care</code>, <code>haha</code>, <code>wow</code>, <code>sad</code>, <code>angry</code> trong <code>extra_metadata.reactions</code>), cùng <code>shares</code>, <code>comments_count</code>, <code>topComments</code>, và <code>extra_metadata.trend_terms</code> (hashtag/sound gốc từ TikTok).</li></ul></li><li><strong>Khử trùng lặp 2 lớp (Two-Tier Deduplication):</strong><ul><li><strong>URL / External ID Dedup:</strong> Loại bỏ ngay các bản ghi trùng chính xác đường dẫn hoặc mã bài đăng.</li><li><strong>Normalized Prefix Hash Dedup:</strong> Băm (<code>SHA-256</code> / fingerprint) 100 ký tự đầu tiên sau chuẩn hóa để phát hiện bài đăng copy-paste re-share hàng loạt qua nhiều fanpage vệ tinh.</li></ul></li></ol><hr><h2 id="_3-kien-truc-t1-—-bot-clone-seeding-filter-kb1–kb6" tabindex="-1">3. Kiến trúc <code>T1</code> — Bot / Clone / Seeding Filter (<code>KB1</code>–<code>KB6</code>) <a class="header-anchor" href="#_3-kien-truc-t1-—-bot-clone-seeding-filter-kb1–kb6" aria-label="Permalink to &quot;3. Kiến trúc `T1` — Bot / Clone / Seeding Filter (`KB1`–`KB6`)&quot;">​</a></h2><p><strong>Đầu vào:</strong> Bình luận thô (<code>topComments</code>), ID tác giả, dấu thời gian đăng và phân bố cảm xúc gốc (giữ nguyên URL/Emoji trước khi xóa để bắt mẫu spam).</p><table tabindex="0"><thead><tr><th style="text-align:left;">Quy tắc</th><th style="text-align:left;">Ngưỡng phát hiện</th><th style="text-align:left;">Hành động trong Pipeline</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>KB1</code> — Velocity</strong></td><td style="text-align:left;">Bình luận dài <code>&gt; 50</code> ký tự nhưng xuất hiện <code>&lt; 5 giây</code> sau khi bài viết lên sóng</td><td style="text-align:left;"><strong>DROP</strong> bình luận (bot auto-reply).</td></tr><tr><td style="text-align:left;"><strong><code>KB2</code> — Frequency</strong></td><td style="text-align:left;">Cùng một <code>author.id</code> bình luận trên <code>&gt; 10</code> bài viết trong <code>&lt; 5 phút</code></td><td style="text-align:left;"><strong>BLACKLIST</strong> toàn bộ <code>author.id</code> trong chu kỳ.</td></tr><tr><td style="text-align:left;"><strong><code>KB3A</code> — Brigading</strong></td><td style="text-align:left;">Tỷ lệ <code>Comments / Total Reactions &gt; 10</code> trong khi tổng tương tác <code>&lt; 20</code></td><td style="text-align:left;"><strong>FLAG <code>anomaly</code></strong> (giảm trọng số ở tầng Engagement <code>T5</code>, không xóa bài).</td></tr><tr><td style="text-align:left;"><strong><code>KB3B</code> — Like-buying</strong></td><td style="text-align:left;">Tổng tương tác <code>&gt; 500</code> nhưng bình luận <code>&lt; 5</code> <strong>hoặc</strong> độ đa dạng reaction <code>&lt; 2</code> loại</td><td style="text-align:left;"><strong>FLAG <code>fake_like</code></strong> (giảm trọng số ở tầng <code>T5</code>).</td></tr><tr><td style="text-align:left;"><strong><code>KB5</code> — Coordinated Burst</strong></td><td style="text-align:left;"><code>&gt; 5</code> tài khoản khác nhau bình luận trên 1 bài trong <code>&lt; 30 giây</code> với độ đa dạng câu chữ <code>&lt; 0.3</code></td><td style="text-align:left;"><strong>BLACKLIST</strong> cụm tài khoản seeding.</td></tr><tr><td style="text-align:left;"><strong><code>KB6</code> — Organic Cross-Post</strong></td><td style="text-align:left;">Cùng một cụm từ/câu có nghĩa xuất hiện tự nhiên bởi nhiều người dùng độc lập trên nhiều bài khác nhau</td><td style="text-align:left;"><strong>BOOST <code>trendSignals[]</code></strong> cho tầng tính điểm đột biến <code>T4</code> &amp; đồ thị <code>T6</code>.</td></tr></tbody></table><hr><h2 id="_4-kien-truc-t2-t2-5-—-nlp-preprocessing-phobert-np-recovery-t2-nlp-step-py" tabindex="-1">4. Kiến trúc <code>T2</code> &amp; <code>T2.5</code> — NLP Preprocessing, PhoBERT &amp; <code>Np</code> Recovery (<code>t2_nlp_step.py</code>) <a class="header-anchor" href="#_4-kien-truc-t2-t2-5-—-nlp-preprocessing-phobert-np-recovery-t2-nlp-step-py" aria-label="Permalink to &quot;4. Kiến trúc `T2` &amp; `T2.5` — NLP Preprocessing, PhoBERT &amp; `Np` Recovery (`t2_nlp_step.py`)&quot;">​</a></h2><p>Trong mã nguồn thực tế (<code>app/services/pipeline/steps/t2_nlp_step.py</code>), class <code>NLPStep</code> thực thi song song làm sạch ngôn ngữ, suy luận mô hình ngôn ngữ tiếng Việt <strong>PhoBERT</strong>, và trích xuất cụm danh từ riêng:</p><h3 id="_4-1-chuoi-lam-sach-van-ban-tieng-viet-nlpstep-process-sync" tabindex="-1">4.1 Chuỗi làm sạch văn bản tiếng Việt (<code>NLPStep._process_sync</code>) <a class="header-anchor" href="#_4-1-chuoi-lam-sach-van-ban-tieng-viet-nlpstep-process-sync" aria-label="Permalink to &quot;4.1 Chuỗi làm sạch văn bản tiếng Việt (`NLPStep._process_sync`)&quot;">​</a></h3><ol><li><strong>Loại bỏ nhiễu cấu trúc:</strong> Xóa URL (<code>http\\S+</code>), thẻ HTML (<code>&lt;[^&gt;]+&gt;</code>), và chuỗi hashtag dính liền (<code>#\\S+</code> — các hashtag quan trọng đã được adapter bảo toàn riêng trong <code>extra_metadata[&quot;trend_terms&quot;]</code>).</li><li><strong>Bảo toàn bảng chữ cái Tiếng Việt đầy đủ (<code>_VN_ALL</code>):</strong> Chỉ giữ ký tự chữ-số và tập nguyên âm có dấu tiếng Việt (<code>àáảãạăắằẳẵặâấầẩẫậ...ỳýỷỹỵđ</code> cả hoa lẫn thường), chuẩn hóa khoảng trắng và chuyển về lowercase lưu vào <code>ctx.cleaned_texts</code>.</li><li><strong>Từ điển Stopwords &amp; Slang (<code>DictionaryLoader</code> &amp; <code>generic_phrase</code>):</strong> Nạp bộ từ dừng tiếng Việt (<code>DictionaryLoader.get_stopwords()</code>) và bộ lọc cụm từ chung chung (<code>app/services/pipeline/quality.py:generic_phrase</code>) để loại bỏ các danh từ báo chí lặp lại ngày nào cũng có (như <code>&quot;khu vực&quot;</code>, <code>&quot;giá trị&quot;</code>, <code>&quot;thời gian&quot;</code>).</li></ol><h3 id="_4-2-gan-nhan-đa-tac-vu-bang-phobert-label-posts-hau-kiem-claude-t2-5" tabindex="-1">4.2 Gán nhãn đa tác vụ bằng PhoBERT (<code>label_posts</code>) &amp; Hậu kiểm Claude (<code>T2.5</code>) <a class="header-anchor" href="#_4-2-gan-nhan-đa-tac-vu-bang-phobert-label-posts-hau-kiem-claude-t2-5" aria-label="Permalink to &quot;4.2 Gán nhãn đa tác vụ bằng PhoBERT (`label_posts`) &amp; Hậu kiểm Claude (`T2.5`)&quot;">​</a></h3><ul><li>Hàm <code>label_posts(texts)</code> (<code>app/services/pipeline/llm_label.py</code> &amp; <code>phobert.py</code>) trả về đồng thời 6 đầu ra cho toàn bộ lô bài viết: <ul><li><code>topics</code> &amp; <code>topic_probs</code>: Chủ đề ngành hàng và độ tự tin <code>ctx.topic_confidence[external_id]</code> (nếu nguồn TikTok đã gắn sẵn <code>extra_metadata[&quot;topic&quot;]</code> thì ưu tiên nhãn gốc của adapter). Các bài có <code>topic_confidence</code> thấp sẽ được bước <code>T2.5</code> (<code>LabelCheckStep</code>) gửi sang Claude phân loại lại.</li><li><code>emotions</code> &amp; <code>emotion_probs</code>: Phân phối xác suất trên <code>EMOTION_LABELS</code> lưu vào <code>ctx.emotion_dists[external_id]</code>.</li><li><code>entities</code> (<code>ctx.ner_entities</code>) &amp; <code>keyphrases</code>: Thực thể định danh (người, tổ chức, địa điểm, sản phẩm, sự kiện) và cụm từ khóa ứng viên.</li></ul></li></ul><h3 id="_4-3-khoi-phuc-cum-danh-tu-rieng-bang-underthesea-pos-tag-extract-noun-phrases" tabindex="-1">4.3 Khôi phục Cụm Danh Từ Riêng bằng <code>underthesea.pos_tag</code> (<code>extract_noun_phrases</code>) <a class="header-anchor" href="#_4-3-khoi-phuc-cum-danh-tu-rieng-bang-underthesea-pos-tag-extract-noun-phrases" aria-label="Permalink to &quot;4.3 Khôi phục Cụm Danh Từ Riêng bằng `underthesea.pos_tag` (`extract_noun_phrases`)&quot;">​</a></h3><p>Vì bộ NER đôi khi bỏ sót tên sản phẩm mới, tên đội tuyển hoặc địa danh check-in viết hoa, <code>t2_nlp_step.py</code> chạy thêm bước quét POS-tag có bộ nhớ đệm <code>@functools.lru_cache(maxsize=4096)</code> trên <strong>400 ký tự đầu giữ nguyên chữ hoa/thường gốc</strong>:</p><ul><li>Chỉ trích xuất các token mang nhãn <strong><code>Np</code> (Proper Noun)</strong> ghép từ 2 âm tiết trở lên (<code>_NOUN_PHRASE_RE</code>), không nằm trong <code>stopwords</code> và không vi phạm <code>generic_phrase()</code>.</li><li>Ghép hợp nhất không trùng lặp theo thứ tự: <code>labeled_phrases</code> (PhoBERT) → <code>extract_noun_phrases()</code> (<code>underthesea</code> <code>Np</code>) → <code>extra_metadata[&quot;trend_terms&quot;]</code> (TikTok hashtags/sounds), đồng thời lưu tập từ gốc tên riêng vào <code>ctx.proper_nouns</code> để cộng điểm ưu tiên ở bước xếp hạng cuối (<code>T7</code>).</li></ul><hr><h2 id="_5-chuan-hoa-cat-nho-tai-lieu-tri-thuc-thuong-hieu-brand-rag-chunking" tabindex="-1">5. Chuẩn hóa &amp; Cắt nhỏ Tài liệu Tri thức Thương hiệu (Brand RAG Chunking) <a class="header-anchor" href="#_5-chuan-hoa-cat-nho-tai-lieu-tri-thuc-thuong-hieu-brand-rag-chunking" aria-label="Permalink to &quot;5. Chuẩn hóa &amp; Cắt nhỏ Tài liệu Tri thức Thương hiệu (Brand RAG Chunking)&quot;">​</a></h2><p>Đối với luồng nạp tài liệu thương hiệu (<code>FR 3.7.1</code>–<code>3.7.2</code>) và bài viết chi tiết của Top Trends vào ChromaDB (<code>client_{clientId}</code>):</p><ul><li>Văn bản sau khi chuẩn hóa Unicode <code>NFC</code> và từ viết tắt mạng xã hội (<code>ko</code> → <code>không</code>, <code>sp</code> → <code>sản phẩm</code>, <code>đc</code> → <code>được</code>) được chia nhỏ bằng <code>RecursiveCharacterTextSplitter</code> với <strong><code>chunk_size = 500</code></strong>, <strong><code>chunk_overlap = 50</code></strong>, ưu tiên cắt tại ranh giới đoạn <code>\\n\\n</code>, xuống dòng <code>\\n</code>, dấu kết câu <code>.</code> / <code>!</code> / <code>?</code> để không làm đứt ngữ nghĩa câu tiếng Việt trước khi sinh vector nhúng <code>384</code> chiều.</li></ul>',28)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
